// 1. Dados do nó anterior
const sessao = $items('Postgres: Busca carrinho cliente')[0].json;
const carrinho = sessao.carrinho_json || [];

const agrupados = {};

// Função para somar itens
function somaItem(id, qtd) {
  if (!agrupados[id]) {
    agrupados[id] = 0;
  }
  agrupados[id] += Number(qtd || 0);
}

// 2. Loop carrinho
for (const item of carrinho) {

  // item principal
  somaItem(item.id, item.qtd);

  // subitens (combo)
  if (item.itens_internos && item.itens_internos.length) {
    for (const sub of item.itens_internos) {
      somaItem(sub.id, sub.qtd);
    }
  }
}

// 3. Converter objeto → array
const itensConsolidados = Object.entries(agrupados).map(([id, qtd]) => ({
  id,
  qtd
}));

return [{
  json: {
    Jid: sessao.jid,
    nome_cliente: sessao.nome_cliente,
    itens: itensConsolidados,
    print_carrinho: sessao.print_carrinho
  }
}];

